'use strict';
// Freeze one real animation frame, then move its parent scroll-view. Compare
// the cyan face pixels with the actor's actual native rectangle displacement.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{spawn}=require('node:child_process');
const root=path.resolve(__dirname,'..'),project=path.resolve(root,'../.rural-quiz-runtime/theme-content-review'),out=path.join(root,'qa/home-designs-20261021'),label=process.argv[2]||'current';
async function call(tool,args=[]){return new Promise((resolve,reject)=>{const c=spawn('/usr/local/bin/wechatide',['-c','Codex',tool,'--project',project,...args]);let s='';c.stdout.on('data',b=>s+=b);c.stderr.on('data',b=>s+=b);const timer=setTimeout(()=>{c.kill();reject(Error(tool+' timeout'));},45000);c.on('close',code=>{clearTimeout(timer);let r;try{r=JSON.parse(s.slice(s.indexOf('{'),s.lastIndexOf('}')+1));}catch{return reject(Error(s.slice(0,600)));}if(code||!r.ok||r.result?.success===false)return reject(Error(r.message||s.slice(0,600)));resolve(r.result);});});}
async function evaluate(fn){let r=await call('automation_evaluate',['--fn-source',fn]);for(let i=0;i<6&&r?.result!==undefined;i++)r=r.result;return r;}
const measure='const q=wx.createSelectorQuery();q.select(".game-device").boundingClientRect();q.select(".panel-body").boundingClientRect();q.select(".route-stop.current .chapter-mascot").boundingClientRect();return {scroll:p.data.mapScrollTop,scrolling:p.data.mapScrolling,playing:c.data.playing,rect:await new Promise(r=>q.exec(r))};';
async function capture(mode,stage){const name='scroll-alignment-'+label+'-'+mode+'-'+stage+'.png';await call('simulator_screenshot',['--path',path.join(out,name),'--optimize','false']);return name;}
async function centroid(file,rects,roi){const sharp=require('./asset-runtime.cjs').sharp(),{data,info}=await sharp(path.join(out,file)).removeAlpha().raw().toBuffer({resolveWithObject:true}),scale=info.width/rects[0].width;let count=0,sx=0,sy=0;for(let y=Math.max(0,Math.floor(roi.top*scale));y<Math.min(info.height,Math.ceil(roi.bottom*scale));y++)for(let x=Math.max(0,Math.floor(roi.left*scale));x<Math.min(info.width,Math.ceil(roi.right*scale));x++){const i=(y*info.width+x)*3,[r,g,b]=data.subarray(i,i+3);if(r<190&&g>160&&b>200&&b>g+8&&g>r+35){count++;sx+=x;sy+=y;}}assert(count>100,'cyan mascot face must remain measurable');return {count,x:sx/count/scale,y:sy/count/scale};}
(async()=>{
 const checks=[];
 for(const mode of ['active','still']){
  await call('automation_navigate',['--action','reLaunch','--url','/pages/game/index?theme=red&review=1&controls=0&scenario=home']);
  const before=await evaluate('async function(){const p=getCurrentPages().slice(-1)[0];await new Promise(r=>setTimeout(r,800));p.focusMap();await new Promise(r=>setTimeout(r,200));const id=p.data.journey.guideId,c=p.selectComponent("#map-actor-"+id);p._motion.dispose();p.setData({motion:{playingId:'+(mode==='active'?'id':'""')+',respondingId:"",sequence:100,touchSequence:0}});await new Promise(r=>setTimeout(r,200));'+(mode==='active'?'c.inspectFrame(.4);':'')+'p._scrollQaTop=p.data.journey.focusTop;'+measure+'}');
  const first=await capture(mode,'before');
  const after=await evaluate('async function(){const p=getCurrentPages().slice(-1)[0],id=p.data.journey.guideId,c=p.selectComponent("#map-actor-"+id),top=Math.max(0,p._scrollQaTop-40);p.setData({mapScrollTop:top});p.onMapScroll({detail:{scrollTop:top}});await new Promise(r=>setTimeout(r,100));'+measure+'}');
  const second=await capture(mode,'after'),a=before.rect[2],b=after.rect[2],roi={left:Math.min(a.left,b.left)-8,right:Math.max(a.right,b.right)+8,top:Math.min(a.top,b.top)-8,bottom:Math.max(a.bottom,b.bottom)+8},one=await centroid(first,before.rect,roi),two=await centroid(second,after.rect,roi),expected=b.top-a.top,actual=two.y-one.y,drift=Math.abs(actual-expected);
  const check={mode,passed:Math.abs(expected)>10&&drift<2,expected,actual,drift,before,after,cyanBefore:one,cyanAfter:two,screenshots:[first,second]};checks.push(check);console.log(JSON.stringify({mode,passed:check.passed,expected,actual,drift}));
 }
 const report={date:new Date().toISOString(),passed:checks.every(c=>c.passed),scope:'Native isolated renderer; a held real animation frame and the still image must follow their parent scroll displacement. Red-theme cyan pixels identify the face; this is not arbitrary-image recognition or physical-phone acceptance.',checks};fs.writeFileSync(path.join(out,'scroll-alignment-'+label+'.json'),JSON.stringify(report,null,2)+'\n');assert(report.passed,'Mascot pixels drift relative to the chapter during scrolling');
})().catch(e=>{console.error(e);process.exitCode=1;});
